const tailFeathers = [
  {x: 120, y: 220, width: 20, height: 15, angle: 0},
  {x: 100, y: 210, width: 25, height: 10, angle: -30},
  {x: 115, y: 230, width: 18, height: 12, angle: 25},
  {x: 140, y: 225, width: 22, height: 9, angle: -15},
  {x: 160, y: 235, width: 24, height: 8, angle: 10},
  {x: 175, y: 215, width: 19, height: 11, angle: -5},
  {x: 190, y: 220, width: 21, height: 10, angle: 0},
  {x: 210, y: 230, width: 16, height: 13, angle: -10}
];

tailFeathers.forEach(f => {
  const [x1, x2] = [f.x + f.width/2, f.x - f.width/2];
  const [y1, y2] = [f.y + f.height/2, f.y - f.height/2];
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx*dx + dy*dy);

  // Rotate and draw
  const cx = f.x;
  const cy = f.y;
  const angle = Math.atan2(dy, dx) + f.angle * Math.PI/180;

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(angle);
  ctx.translate(-cx, -cy);

  ctx.fillStyle = '#1E90FF';
  ctx.fillRect(x1, y1, f.width, f.height);

  // Feather tip
  ctx.fillStyle = '#4682B4';
  ctx.fillRect(x1 - 3, y1 - 2, 6, 4);

  ctx.restore();
});

