// Cool tones for a spiral pattern
const SKY = '#0a1929';
const GROUND = '#1a3a52';
const ACCENT = '#4ecdc4';
const SHADOW = '#2c7fb1';
const HIGHLIGHT = '#b5e3da';

// Draw sky background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral in cool tones
function drawSpiral(x, y, radius, count) {
    if (count === 0) return;

    // Draw outer circle with shadow
    ctx.fillStyle = SHADOW;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Draw inner circle with highlight
    ctx.fillStyle = HIGHLIGHT;
    ctx.beginPath();
    ctx.arc(x, y, radius - 5, 0, Math.PI * 2);
    ctx.fill();

    // Draw spiral arms
    ctx.strokeStyle = ACCENT;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(count) * (radius - 10), y + Math.sin(count) * (radius - 10));
    ctx.stroke();

    // Recursive call for next segment
    drawSpiral(
        x + Math.cos(count) * (radius - 10),
        y + Math.sin(count) * (radius - 10),
        radius - 10,
        count + 0.25
    );
}

