// Shell spiral
ctx.fillStyle = '#8B4513';
ctx.beginPath();
let radius = 0;
for (let i = 0; i < 20; i++) {
    const angle = (i * 0.3 + Date.now() / 100) % Math.PI * 2;
    const r = radius + (i + 1) * 5;
    const x = 200 + Math.cos(angle) * r;
    const y = 250 + Math.sin(angle) * r;

    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);

    radius = r;
}
ctx.closePath();
ctx.fill();

// Shell details
ctx.fillStyle = '#A0522D';
for (let i = 0; i < 20; i++) {
    const angle = (i * 0.4 + Date.now() / 100) % Math.PI * 2;
    const r = radius + (i + 1) * 3;
    const x = 200 + Math.cos(angle) * r;
    const y = 250 + Math.sin(angle) * r;
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
}

